begin;

-- ---------------------------------------------------------------- auth.users
create temp table _seed_users (id uuid, email text, name text, role text) on commit drop;
  confirmation_token, recovery_token, email_change_token_new, email_change, email_change_token_current,
  phone_change, phone_change_token, reauthentication_token,
  raw_app_meta_data, raw_user_meta_data, is_super_admin, created_at, updated_at, last_sign_in_at)
select '00000000-0000-0000-0000-000000000000', u.id, 'authenticated', 'authenticated', u.email, h.pw, now(),
  '', '', '', '', '', '', '', '',
  '{"provider":"email","providers":["email"]}'::jsonb,
  jsonb_build_object('name', u.name, 'seed_role', u.role), false, now() - interval '180 days', now(), null
from _seed_users u
cross join (select extensions.crypt('Joints123!', extensions.gen_salt('bf')) as pw) h;
select u.id::text, u.id, jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true),
  'email', null, now() - interval '180 days', now()
from _seed_users u;

